mapper.select:
SELECT P.POST_SEQ AS "postSeq" , P.POST_TTL AS "title" , P.POST_CN AS "description" , R.RCP_CTG_CD AS "categoryCode" , CT.COM_DTL_DESC AS "categoryName" , R.COOK_MIN AS "cookingMinutes" , R.SERV_QTY AS "servings" , R.RCP_DIF_CD AS "difficultyCode" , DF.COM_DTL_DESC AS "difficultyName" , P.USR_ID AS "authorId" , U.NCK_NM AS "authorName" , U.PRFL_IMG_FIL_SEQ AS "profileImageFilSeq" , TO_CHAR(P.POST_DTM, 'YYYY-MM-DD"T"HH24:MI:SS') AS "createdAt" , (SELECT COUNT(*) FROM moa.TB_COMM_POST_LIKE L WHERE L.POST_SEQ = P.POST_SEQ) AS "likeCount" , (SELECT COUNT(*) FROM moa.TB_COMM_POST_SAVE S WHERE S.POST_SEQ = P.POST_SEQ) AS "saveCount" , EXISTS ( SELECT 1 FROM moa.TB_COMM_POST_SAVE S WHERE S.POST_SEQ = P.POST_SEQ AND S.USR_ID = #{usrId} ) AS "savedByMe" , (P.USR_ID = #{usrId}) AS "mine" FROM moa.TB_COMM_POST P JOIN moa.TB_RCP R ON R.POST_SEQ = P.POST_SEQ JOIN moa.TB_USR U ON U.USR_ID = P.USR_ID LEFT JOIN moa.TB_COM_CD_DTL CT ON CT.COM_CD = 'RCP_CTG' AND CT.COM_DTL_CD = R.RCP_CTG_CD LEFT JOIN moa.TB_COM_CD_DTL DF ON DF.COM_CD = 'RCP_DIF' AND DF.COM_DTL_CD = R.RCP_DIF_CD WHERE P.POST_STAT IN (#{postActive}, 'ACTIVE') AND ( P.VIS_TYP IN (#{publicVisibility}, 'PUBLIC') OR P.USR_ID = #{usrId} OR EXISTS ( SELECT 1 FROM moa.TB_COMM_FOLLOW F WHERE F.FOLLOWER_USR_ID = #{usrId} AND F.FOLLOWING_USR_ID = P.USR_ID AND F.FOLLOW_STAT IN (#{followAccepted}, 'ACCEPTED') ) ) AND ( #{scope} = 'all' OR (#{scope} = 'mine' AND P.USR_ID = #{usrId}) OR ( #{scope} = 'saved' AND EXISTS ( SELECT 1 FROM moa.TB_COMM_POST_SAVE S WHERE S.POST_SEQ = P.POST_SEQ AND S.USR_ID = #{usrId} ) ) )
AND R.RCP_CTG_CD = #{categoryCode}
AND ( #{query} = '' OR P.POST_TTL ILIKE '%' || #{query} || '%' OR P.POST_CN ILIKE '%' || #{query} || '%' OR EXISTS ( SELECT 1 FROM moa.TB_RCP_INGR RI WHERE RI.POST_SEQ = P.POST_SEQ AND RI.INGR_NM_SNAP ILIKE '%' || #{query} || '%' ) ) ORDER BY (P.USR_ID = #{usrId}) DESC , (SELECT COUNT(*) FROM moa.TB_COMM_POST_SAVE S WHERE S.POST_SEQ = P.POST_SEQ) DESC , P.POST_DTM DESC LIMIT #{limit}

mapper.insert:
INSERT INTO moa.TB_COMM_POST (
    POST_SEQ
    , USR_ID
    , POST_TTL
    , POST_CN
    , POST_STAT
    , VIS_TYP
    , POST_DTM
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{usrId}
    , #{title}
    , #{description}
    , #{postStat}
    , #{visibility}
    , CURRENT_TIMESTAMP
    , #{frstRegUserId}
)

INSERT INTO moa.TB_RCP (
    POST_SEQ
    , RCP_CTG_CD
    , COOK_MIN
    , SERV_QTY
    , RCP_DIF_CD
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{categoryCode}
    , #{cookingMinutes}
    , #{servings}
    , #{difficultyCode}
    , #{frstRegUserId}
)

INSERT INTO moa.TB_RCP_INGR (
    POST_SEQ
    , SORT_ORD
    , INGR_GRP_CD
    , INGR_CD
    , INGR_NM_SNAP
    , INGR_AMT
    , UNIT_CD
    , NOTE
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{sortOrd}
    , #{ingredientGroupCode}
    , #{ingredientCode}
    , #{ingredientName}
    , #{ingrAmt}
    , #{unitCode}
    , #{note}
    , #{frstRegUserId}
)

INSERT INTO moa.TB_RCP_STP (
    POST_SEQ
    , STEP_NO
    , STEP_CN
    , COOK_SEC
    , STEP_FIL_SEQ
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{stepNo}
    , #{content}
    , #{cookSec}
    , #{stepFilSeq}
    , #{frstRegUserId}
)

INSERT INTO moa.TB_COMM_POST_SAVE (
    POST_SEQ
    , USR_ID
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{usrId}
    , #{usrId}
)
ON CONFLICT DO NOTHING

mapper.delete:
DELETE FROM moa.TB_COMM_POST_SAVE
 WHERE POST_SEQ = #{postSeq}
   AND USR_ID = #{usrId}
